package dev.zz.laptracker

import android.Manifest
import android.app.Activity
import android.content.ClipData
import android.content.ClipboardManager
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.graphics.Color
import android.graphics.Typeface
import android.location.LocationManager
import android.net.Uri
import android.os.*
import android.provider.Settings
import android.view.Gravity
import android.view.ViewGroup
import android.widget.*
import java.util.Calendar
import java.util.Locale

class MainActivity:Activity(){
 private lateinit var statusView:TextView;private lateinit var distanceView:TextView;private lateinit var elapsedView:TextView;private lateinit var speedView:TextView;private lateinit var avgView:TextView;private lateinit var accelView:TextView;private lateinit var autoBtn:Button;private lateinit var dailySummaryView:TextView
 private val ui=Handler(Looper.getMainLooper());private val listener:()->Unit={render()};private val tick=object:Runnable{override fun run(){render();ui.postDelayed(this,1000)}};private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt()
 private val clipboardListener=ClipboardManager.OnPrimaryClipChangedListener{checkClipboard()}
 override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),dp(16),dp(16),dp(16));setBackgroundColor(Color.BLACK)};val header=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL};header.addView(TextView(this).apply{text="Lap Tracker";textSize=22f;setTypeface(null,Typeface.BOLD);setTextColor(Color.WHITE)},LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));header.addView(Button(this).apply{text="History";setOnClickListener{startActivity(Intent(this@MainActivity,HistoryActivity::class.java))}});header.addView(Button(this).apply{text="Analysis";setOnClickListener{startActivity(Intent(this@MainActivity,AnalyticsActivity::class.java))}});root.addView(header);statusView=TextView(this).apply{textSize=14f;setTextColor(Color.LTGRAY);setPadding(0,dp(6),0,dp(4))};root.addView(statusView);distanceView=TextView(this).apply{textSize=56f;setTypeface(null,Typeface.BOLD);setTextColor(Color.WHITE);gravity=Gravity.CENTER;setPadding(0,dp(4),0,dp(8))};root.addView(distanceView);val stats=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};speedView=addStat(stats,"Speed");avgView=addStat(stats,"Average");accelView=addStat(stats,"Accel m/s²");elapsedView=addStat(stats,"Ride time");root.addView(stats);autoBtn=Button(this).apply{textSize=18f;setOnClickListener{onAutoClicked()}};root.addView(autoBtn,LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(58)));root.addView(Button(this).apply{text="Check copied number";setOnClickListener{if(!checkClipboard())Toast.makeText(this@MainActivity,"No Pakistani 03xxxxxxxxx number found in clipboard",Toast.LENGTH_SHORT).show()}});root.addView(Button(this).apply{text="Enable inDrive notification access";setOnClickListener{try{startActivity(Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"))}catch(_:Exception){startActivity(Intent(Settings.ACTION_SETTINGS))}}});root.addView(Button(this).apply{text="Fix notification access / restricted settings";setOnClickListener{try{startActivity(Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:$packageName")))}catch(_:Exception){startActivity(Intent(Settings.ACTION_SETTINGS))}}});root.addView(TextView(this).apply{text="Rides are detected automatically after sustained movement and end after 8 minutes stopped.\n\nClipboard: Android limits background clipboard access. When Lap Tracker is visible, copied Pakistani 03xxxxxxxxx numbers are detected immediately. The Check copied number button tests the current clipboard.";textSize=13f;setTextColor(Color.LTGRAY);setPadding(0,dp(8),0,dp(8))});root.addView(TextView(this).apply{text="Today's Summary";textSize=16f;setTypeface(null,Typeface.BOLD);setTextColor(Color.WHITE);setPadding(0,dp(10),0,dp(4))});dailySummaryView=TextView(this).apply{textSize=14f;setTextColor(Color.LTGRAY)};root.addView(dailySummaryView);setContentView(root)}
 private fun addStat(row:LinearLayout,label:String):TextView{val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER};val value=TextView(this).apply{textSize=18f;setTypeface(null,Typeface.BOLD);setTextColor(Color.WHITE);gravity=Gravity.CENTER};box.addView(value);box.addView(TextView(this).apply{text=label;textSize=11f;setTextColor(Color.LTGRAY);gravity=Gravity.CENTER});row.addView(box,LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));return value}
 override fun onStart(){super.onStart();TrackerBus.addListener(listener);ui.post(tick);(getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager).addPrimaryClipChangedListener(clipboardListener);checkClipboard()};override fun onStop(){super.onStop();TrackerBus.removeListener(listener);ui.removeCallbacks(tick);(getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager).removePrimaryClipChangedListener(clipboardListener)}
 private fun extractNumber(text:String):String?{val normalized=text.replace("+92","0").replace("0092","0").replace(Regex("[\\s().-]"),"");return Regex("(?<!\\d)(03\\d{9})(?!\\d)").find(normalized)?.value}
 private fun checkClipboard():Boolean{val number=try{val cm=getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager;if(!cm.hasPrimaryClip())return false;val clip:ClipData=cm.primaryClip?:return false;extractNumber(clip.getItemAt(0).coerceToText(this).toString())}catch(_:Exception){null};if(number!=null)Toast.makeText(this,"Detected $number",Toast.LENGTH_SHORT).show();return number!=null}
 private fun render(){val s=TrackerBus.state;val now=System.currentTimeMillis();val elapsed=if(s.startTime==0L)0L else if(s.sessionId!=0L)now-s.startTime else s.endTime-s.startTime;distanceView.text=Fmt.km(s.distanceM);speedView.text=if(s.hasFix)Fmt.speedKmh(s.speedMs.toDouble()) else "–";avgView.text=if(elapsed>0&&s.distanceM>0)Fmt.speedKmh(s.distanceM/(elapsed/1000.0)) else "–";accelView.text=s.accelerationMs2?.let{String.format(Locale.US,"%.1f",it)}?:"–";elapsedView.text=Fmt.duration(elapsed);autoBtn.text=if(s.running)"AUTO TRACKING ON — Turn off" else "AUTO TRACKING OFF — Turn on";statusView.text=when{!s.running->"Ready. Turn on auto tracking. Your rides will be detected automatically.";!s.locationOn->"Location is off — waiting for GPS.";s.sessionId==0L->"Monitoring · waiting for movement to start a ride…";!s.hasFix->"Ride active · waiting for a good GPS fix…";else->"Ride active · GPS ±${s.accuracyM?.toInt()?:0} m · 1-second samples"};updateDailySummary()}
 private fun updateDailySummary(){val cal=Calendar.getInstance();cal.set(Calendar.HOUR_OF_DAY,0);cal.set(Calendar.MINUTE,0);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);val start=cal.timeInMillis;cal.add(Calendar.DAY_OF_MONTH,1);val d=Db.get(this).getTodaySummary(start,cal.timeInMillis);dailySummaryView.text="Distance: ${Fmt.km(d.distanceM)}  ·  Tracking: ${Fmt.duration(d.durationMs)}\nRides: ${d.sessionCount}  ·  Ride events: ${d.lapCount}  ·  Call events: ${d.callCount}\nOpen History for rides or Analysis for acceleration/fuel."}
 private fun granted(p:String)=checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED
 private fun onAutoClicked(){if(TrackerBus.state.running){startService(Intent(this,TrackingService::class.java).setAction(TrackingService.ACTION_STOP));return};val needed=ArrayList<String>();if(!granted(Manifest.permission.ACCESS_FINE_LOCATION)){needed.add(Manifest.permission.ACCESS_FINE_LOCATION);needed.add(Manifest.permission.ACCESS_COARSE_LOCATION)};if(Build.VERSION.SDK_INT>=33&&!granted(Manifest.permission.POST_NOTIFICATIONS))needed.add(Manifest.permission.POST_NOTIFICATIONS);if(!granted(Manifest.permission.READ_PHONE_STATE))needed.add(Manifest.permission.READ_PHONE_STATE);if(!granted(Manifest.permission.READ_CALL_LOG))needed.add(Manifest.permission.READ_CALL_LOG);if(!granted(Manifest.permission.CALL_PHONE))needed.add(Manifest.permission.CALL_PHONE);if(needed.isEmpty())beginMonitoring()else requestPermissions(needed.toTypedArray(),7)}
 override fun onRequestPermissionsResult(requestCode:Int,permissions:Array<out String>,grantResults:IntArray){super.onRequestPermissionsResult(requestCode,permissions,grantResults);if(granted(Manifest.permission.ACCESS_FINE_LOCATION))beginMonitoring()else Toast.makeText(this,"Precise location permission is required",Toast.LENGTH_LONG).show()}
 private fun beginMonitoring(){val lm=getSystemService(Context.LOCATION_SERVICE) as LocationManager;if(!lm.isLocationEnabled)Toast.makeText(this,"Turn on Location for automatic ride detection",Toast.LENGTH_LONG).show();try{startForegroundService(Intent(this,TrackingService::class.java).setAction(TrackingService.ACTION_START))}catch(e:Exception){Toast.makeText(this,"Could not start auto tracking: ${e.message}",Toast.LENGTH_LONG).show()}}
}
